def find_jump_max_heights(heights, height_changes):
    max_height, current_height = heights[0], heights[0]
    max_length = 1
    for i in range(1, len(heights)):
        jump = True
        while i < len(height_changes) and height_changes[i]-1 < i:
            if i == len(height_changes):
                jump = False
            elif height_changes[i]-1 == i:
