def _factorize(num):
    factors = []
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            factors.append(i)
            if i != num // i:
                factors.append(num // i)
            break
    if num != 1:
        factors.append(num)
    return factors
