def minimum_inversions(n, arr):
    arr = [0] + arr + [10**9 + 1]
    prefix_sum = [0]
    for num in arr:
        prefix_sum.append(prefix_sum[-1] + num)

    min_inversions = float('inf')
    for i in range(1, n + 1, 2):
        for j in range(i + 1, n + 1, 2):
            right_range_sum = prefix_sum[j + 1] - prefix_sum[i]
            left_range_sum = prefix_sum[n] - prefix_sum[i] - (prefix_sum[j] - prefix_sum[i])
            inversion_count = left_range_sum - right_range_sum + (min(i, j) * 2)
            min_inversions = min(min_inversions, inversion_count)

    for inversion in range(1, n + 1, 2):
        if inversion_count < min_inversions:
            min_inversions = inversion_count
            selected_inversion = [i, i + 1]

    for i in range(1, n + 1, 2):
        if i + 1 not in selected_inversion and inversion_count > min_inversions:
            selected_inversion.append(i + 1)

    return selected_inversion


