                    dp[i][removal_count] = (dp[i][removal_count] + dp[i - 1][removal_count - num]) % 998244353
                else:
                    dp[i][removal_count] = (dp[i][removal_count] + dp[i - 1][removal_count]) % 998244353
    return dp[n][k]

def find_division_modes(arr, k):
    n = len(arr)
    arr_count = dict(Counter(arr))
    total_removals = sum(arr_count.values())
    valid_removals_count = 0
    for removal_count in range(k + 1):
        valid_removals_count = (valid_removals_count + valid_removals(arr, k - removal_count) % 998244353) % 998244353
    return valid_removals_count ** n % 998244353

