            self.points[(x, y)].pop()

    def find_closest_point(self, x, y):
        if (x, y) not in self.points:
            return -1
        points = sorted(self.points[(x, y)], key=lambda pt: (pt[0], pt[1]))
        return points[-1]

def process_request(request_type, coordinates, finder):
