def is_removal_needed(end_index, prev_index):
    return len(end_index) < len(prev_index) or (len(end_index) == len(prev_index) and end_index < prev_index)

def dfs(s, start_index, end_index):
    stack = deque()
    min_index = start_index

    while stack or start_index <= end_index:
        if s[start_index] < s[end_index]:
            min_index = min(min_index, is_removal_needed(stack, s[start_index:end_index + 1]))
            start_index += 1
        else:
            stack.append(s[start_index])
            end_index += 1

    return len(s[start_index:end_index + 1]) - min_index

def subsequence_length(subsequence):
    max_depth = 0
    max_subsequence = []

    for r in range(len(subsequence)):
        if len(subsequence[r]) > max_depth:
            max_depth = len(subsequence[r])
            max_subsequence = [r]

