from sys import stdin
import math

MOD = 10**9 + 7

def lcm(a, b):
    return a * b // math.gcd(a, b)

def main():
    n = int(stdin.readline().strip())
    tasks = [list(map(int, stdin.readline().strip().split())) for _ in range(n)]
    s_size = int(stdin.readline().strip())
    s = list(map(int, stdin.readline().strip().split()))
    times = [0] * n + tasks + s
    times.sort()
    time_differences = [times[i + 1] - times[i] for i in range(n + s_size)]

    # Find the start of the set s_gaps which is the gaps BEFORE s
    for i in range(s_size):
        for gap in time_differences[:-n]:
            if gap == s[i] - 1:
                s_gaps = time_differences[s_size - i - 1:s_size - i + n - 1]
                break
        else:
            expected_gaps = [lcm(a, b) for a, b in zip(time_differences[:-n], reversed(times[::-1][:n]))]
            s_gaps = sum(map(lambda x, y: min(x, y), expected_gaps, time_differences[:-n]))
            continue

    # Also find the start of the divide gaps which is the gaps AFTER s
    for i in range(s_size):
        for gap in time_differences[n:]:
            if gap == s[-i] + n + 1 - i:
                divide_gaps = time_differences[:-s_size][::-1][s_size - i:]
                break
        else:
            expected_gaps = [lcm(a, b) for a, b in zip(time_differences[:n], reversed(times))][n:2*n]
            divide_gaps = sum(map(lambda x, y: min(x, y), expected_gaps, time_differences[s_size - i:]))

    # Main loop to compute the number of time travels before the funny scene
    time_travel_tracker = 0
    for gap in divide_gaps:
        time_travel_tracker += gap
        time_travel_tracker %= MOD
    return time_travel_tracker

if __name__ == "__main__":
    print(main())
