from math import pow, modinv
from collections import Counter
from typing import List

MOD = 998244353

class SegmentTree:
    def __init__(self, size):
        self.size = size
        self.tree = [0] * (size*4)
        self.lazy = [0] * (size*4)

    def build(self, nums):
        for i in range(self.size, 0, -1):
            self.tree[i] = nums[i-1]
            self.lazy[i] = 0

    def update(self, l, r, val, node=1, node_start=1, node_end=self.size):
        if l <= node_start and node_end <= r:
            self.tree[node] = val
            self.lazy[node] = 0
            return

        self.shrink_update(l, r, val, node * 2, node_start, (node_start + node_end) // 2)
        self.shrink_update(l, r, val, node * 2 + 1, (node_start + node_end) // 2 + 1, node_end)

        self.tree[node] = (self.tree[node * 2] + self.tree[node * 2 + 1]) % MOD

    def shrink_update(self, l, r, val, node=1, node_start=1, node_end=self.size):
        lazy = self.lazy[node]
        self.lazy[node] = 0

        if lazy != 0:
            self.accumulate(node * 2, l, r, val + lazy, MOD)
            self.accumulate(node * 2 + 1, l, r, val + lazy, MOD)
            self.tree[node] = (self.tree[node * 2] + self.tree[node * 2 + 1] - (lazy * (node_end-node_start)) % MOD * 1000000007 + MOD) % MOD

        if hasattr(self, 'accumulate'):
            self.accumulate(node * 2, l, r, val + lazy, MOD)
            self.accumulate(node * 2 + 1, l, r, val + lazy, MOD)
            self.lazy[node] = lazy

        if hasattr(self, 'accumulate'):
            self.accumulate(node * 2, l, r, val + lazy, MOD)
            self.accumulate(node * 2 + 1, l, r, val + lazy, MOD)
            self.lazy[node] = lazy

    def query(self, l, r, node=1, node_start=1, node_end=self.size):
        if not (l <= node_start and node_end <= r):
            return 0

        if l <= node_start and node_end <= r:
            self.accumulate(node, l, r, 0, MOD)
            return self.tree[node]

        self.shrink_update(l, r, 0)
        q1 = self.query(l, r, node * 2, node_start, (node_start + node_end) // 2)
        q2 = self.query(l, r, node * 2 + 1, (node_start + node_end) // 2 + 1, node_end)
        if hasattr(self, 'accumulate'):
            q1 += q2
            self.accumulate(node, l, r, q1, MOD)
        return q1 % MOD

    def accumulate(self, node, start, end, val, MOD):
        self.lazy[node] = 0

        if start < end and start <= self.size - self.size and end >= self.size - self.size:
            self.accumulate(node * 2, start, end, val, MOD)
            self.accumulate(node * 2 + 1, start, end, val, MOD)

        self.tree[node] = (self.tree[node * 2] + self.tree[node * 2 + 1] + val) % MOD


class Solution:
    def countSegments(self, a: List[int], k: int) -> int:
        n = len(a)
        segtree = SegmentTree(n+1)
        a = [0] + a
        segtree.build(a)

        count = pow(2, n, MOD)
        for i in range(1, n+1):
            segment = Counter(a[i-1:i+1])
            for x in segment.keys():
                x_count = segment[x]
                if x_count - 1 < k - 1:
                    continue
                if i == n and x == n:
                    result = pow(x_count, -1 % MOD, MOD)
                    result = (x_count * result) % MOD
                else:
                    result = (x_count * segtree.query(i-1, i+1, 1, 1, n+1)) % MOD
                count = (count * result) % MOD

        return int(count)

