# Function to calculate the modular inverse of a under mod p
def mod_inverse(a, p):
    x, y = 1, 0
    while a != 0:
        q = p // a
        a, p = p % a, a
        x, y = y - q * x, x
    assert a == 1
    return y % p

# Function to perform modular addition
def mod_add(a, b, p):
    return a % p + b % p

# Function to perform modular subtraction
def mod_sub(a, b, p):
    return a % p - b % p

