import math
from functools import lru_cache

def divide_segments(n, k, a):
    @lru_cache(maxsize=None)
    def dp(index, last_digit, complete_count):
        if index == n:
            return int(complete_count > 0)

        # Option 1: Not to take current number
        without_digit = dp(index + 1, last_digit, complete_count)

        # Option 2: Take current number
        if last_digit != a[index]:
            complete_count += 1
            include_digit = dp(index + 1, a[index], complete_count)

        return (without_digit + include_digit) % 998244353

    return dp(0, -1, 0)

