        visited = set()
        stack = [(x, y)]
        while stack:
            u, v = stack.pop()
            if (v > y) and (v not in visited):
                visited.add(v)
                leftmost_above = v
            if u in self.graph:
                for neighbor in self.graph[u]:
                    if neighbor != v and neighbor not in visited:
                        stack.append((neighbor, v))
