class BottomLeftFinder:
    def __init__(self, n):
        self.points = []

    def add(self, x, y):
        leftmost = (y, x)
        for point in self.points:
            if point[0] < leftmost[0]:
                leftmost = point
            elif point[0] == leftmost[0] and point[1] < leftmost[1]:
                leftmost = point
        self.points.remove(leftmost)
        self.points.append((y, x))

    def remove(self, x, y):
        self.points = [point for point in self.points if point != (y, x)]

    def find(self, x, y):
        if 1 in (point[0] - x for point in self.points) or 1 in (point[1] - y for point in self.points):
            bottommost = max(self.points, key=lambda point: point[0] if point[0] > y else -1)
            return [bottommost[0] + x, bottommost[1] + y]
        else:
            return -1

