    counts = defaultdict(int)
    for val in arr:
        counts[val] += 1
    return max(counts, key=counts.get)

def ugliness(s):
    """Compute the ugliness of the string s"""
    n = len(s)
    # Find the majority digit digit in each position
    majority = ''
    for i in range(n):
        if s[i] == '9':
            majority += '9'
        else:
            majority += '0'
    # Compute the ugliness for all windows of size n-1
    uglinesses = []
    current_ugliness = 0
    for i in range(n-1):
        current_ugliness += 1
        for j in range(i, n-1):
            if s[j] != majority[i % 2]:
                current_ugliness -= 1
            if current_ugliness < 1:
                break
            if s[j] > majority[i % 2]:
                current_ugliness = 0
        uglinesses.append(current_ugliness)
    # Compute the ugliness for the last window
    current_ugliness = ugly(n-1, majority[n-1 % 2], s)
    uglinesses.append(current_ugliness)
    return max(uglinesses)

def ugly(n, last_char, s):
    """Compute the ugliness of a string of length n ending with last_char without the first character being last_char"""
    if n == 1:
        return 1

    # Compute all ugly final occurrences
    uglys = list(range(n))
    for i in range(1, n):
        uglys[0] = min(uglys[0]+1, uglys[i])

    div, rem = divmod(n-1, len(set([c for c in s if c != last_char])))
    for i in range(1, 4*(n-1)//len(set([c for c in s if c != last_char]))) - div:
        rem += 1
        if rem <= n:
            uglys[n-1-rem] = ugly(uglys[n-1-rem]+1, last_char, s)
        else:
            uglys[div-1] = min(uglys[div-1]+1, uglys[div-1+rem])  
    return min(uglys)

