def digit_cost(x):
    if x == '?':
        return 0
    return int(x)

def max_collection_cost(A, n, Bi, cd):
    artifact_length = len(A)
    cost = [0] + list(map(digit_cost, A))
    max_cost = 0
    for i in range(n):
        current_cost = cost[i]
        for j in range(10):
            new_cost = current_cost + cd[j]
            new_number = str(Bi[i])
            new_number = new_number.replace('?', str(j))
            new_cost += cost(int(new_number))
            if new_cost > max_cost:
                max_cost = new_cost
    return max_cost
